WITH base AS (SELECT *, INITCAP(TRIM(event_type)) AS event_type_title FROM web_events WHERE event_time > DATE '2023-08-21') SELECT id, page, event_time, duration_sec, event_type_title, COUNT(duration_sec) OVER (PARTITION BY event_type ORDER BY CAST(event_time AS BIGINT) ASC RANGE BETWEEN 7776000 PRECEDING AND CURRENT ROW) AS duration_sec_count_90d, LEAD(duration_sec, 1, 0) OVER (PARTITION BY page ORDER BY duration_sec ASC, id ASC) AS next_duration_sec, AVG(duration_sec) OVER (PARTITION BY session_id ORDER BY event_time ASC, id ASC ROWS BETWEEN 5 PRECEDING AND 1 PRECEDING) AS duration_sec_avg_5_prior FROM base WHERE event_type NOT IN ('add_to_cart', 'click')
